const principal = view(Inputs.range([100, 10000], {label: "Start with (€)", step: 100, value: 1000}))
const rate = view(Inputs.range([1, 20], {label: "Interest per year (%)", step: 0.5, value: 7}))
const years = view(Inputs.range([1, 60], {label: "Years", step: 1, value: 30}))
const topup = view(Inputs.range([0, 500], {label: "Add each year (€)", step: 10, value: 0}))

const rows = (() => {
  const r = rate / 100; let c = principal, s = principal, out = [];
  for (let y = 0; y <= years; y++) {
    out.push({year: y, compound: c, simple: s});
    c = c * (1 + r) + topup; s = s + principal * r + topup;
  }
  return out;
})()

(() => {
  const last = rows[rows.length - 1], f = d3.format(",.0f");
  const extra = last.compound - last.simple;
  return htl.html`<div>
  <div style="display:flex;gap:24px;flex-wrap:wrap;margin:8px 0">
    <div><b style="font-size:1.6em">€${f(last.compound)}</b><br>with compound interest</div>
    <div><b style="font-size:1.6em">€${f(last.simple)}</b><br>with simple interest (same % on the start amount only)</div>
    <div><b style="font-size:1.6em">€${f(extra)}</b><br>bonus from "interest on interest"</div>
