htl.html`<div style="display:grid;grid-template-columns:repeat(auto-fit,minmax(150px,1fr));gap:10px">
${kpis.map(k=>{
  const d = +(k.now-k.prev).toFixed(1), pct = Math.round(d/k.prev*100);
